import React, { useState } from "react";
import { useAuth } from "../context/AuthContext";
import "../styles/Stocks.css"

function Stocks() {
  const [searchTerm, setSearchTerm] = useState(""); // Controla lo que se escribe en el input
  const [suggestions, setSuggestions] = useState([]); // Lista de opciones
  const [selectedStock, setSelectedStock] = useState(null); // Almacena el stock seleccionado
  const { token } = useAuth();

  const fetchSuggestions = async (term) => {
    try {
      const response = await fetch(`/api/stocks/search?query=${term}`, { // Endpoint para buscar sugerencias
        method: "GET",
        headers: {
          "Authorization": `Bearer ${token}`,
        },
      });
      if (!response.ok) {
        throw new Error(`Error al obtener sugerencias: ${response.statusText}`);
      }
      const data = await response.json();
      setSuggestions(data); // Actualiza la lista de sugerencias
    } catch (error) {
      console.error("Error al obtener sugerencias:", error.message);
      setSuggestions([]);
    }
  };

  const handleInputChange = (e) => {
    const term = e.target.value;
    setSearchTerm(term);
    if (term.length >= 2) { // Empieza a buscar después de 2 caracteres
      fetchSuggestions(term);
    } else {
      setSuggestions([]); // Limpia sugerencias si no hay suficientes caracteres
    }
  };

  const handleSuggestionClick = (stock) => {
    setSearchTerm(stock.name); // Muestra el nombre del stock seleccionado en el input
    setSelectedStock(stock); // Guarda el stock seleccionado
    setSuggestions([]); // Limpia las sugerencias después de seleccionar
  };

  return (
    <div className="container">
      <h1>Selecciona tu Stock</h1>
      <input
        type="text"
        placeholder="Busca un Stock"
        value={searchTerm}
        onChange={handleInputChange} // Llama a la función al escribir
      />
      {suggestions.length > 0 && ( // Renderiza las sugerencias si existen
        <ul className="suggestions">
          {suggestions.map((stock) => (
            <li
              key={stock.id}
              onClick={() => handleSuggestionClick(stock)}
              className="suggestion-item"
            >
              {stock.name} ({stock.symbol})
            </li>
          ))}
        </ul>
      )}
      {selectedStock && (
        <div className="result">
          <h3>Stock seleccionado:</h3>
          <pre>{JSON.stringify(selectedStock, null, 2)}</pre>
        </div>
      )}
    </div>
  );
}

export default Stocks;
